<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/../includes/functions.php';$pageTitle='Student Transcript';require_role(['admin']);require_once __DIR__.'/../includes/header.php';
$students=$pdo->query("SELECT id,admission_no,surname,firstname,othername FROM students ORDER BY surname,firstname LIMIT 5000")->fetchAll();$studentId=(int)($_GET['student_id']??0);$year=trim($_GET['year']??'');$record=null;$rows=[];if($studentId){$q=$pdo->prepare('SELECT s.*,c.name class_name,c.section FROM students s LEFT JOIN classes c ON c.id=s.class_id WHERE s.id=?');$q->execute([$studentId]);$record=$q->fetch();if($record){$sql='SELECT r.*,sub.subject_name,t.session_name,t.term_name FROM results r JOIN subjects sub ON sub.id=r.subject_id JOIN academic_terms t ON t.id=r.term_id WHERE r.student_id=?';$args=[$studentId];if($year!==''){$sql.=' AND t.session_name=?';$args[]=$year;}$sql.=' ORDER BY t.session_name,t.id,sub.subject_name';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();}}$years=$pdo->query('SELECT DISTINCT session_name FROM academic_terms ORDER BY session_name DESC')->fetchAll(PDO::FETCH_COLUMN);
?><h2>Student Result Transcript</h2><div class="card p-3 mb-3"><form method="get" class="row g-2"><div class="col-md-6"><label>Student</label><select class="form-select" name="student_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=$studentId===(int)$s['id']?'selected':''?>><?=e($s['admission_no'].' — '.$s['surname'].' '.$s['firstname'].' '.$s['othername'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Academic year (leave blank for all years)</label><select class="form-select" name="year"><option value="">All years</option><?php foreach($years as $y):?><option <?=$year===$y?'selected':''?>><?=e($y)?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Generate</button></div></form></div><?php if($record):?><div class="card p-4" id="transcript"><h3><?=e(setting($pdo,'school_name'))?></h3><h4>Academic Result Transcript</h4><p><b>Student:</b> <?=e($record['surname'].' '.$record['firstname'].' '.$record['othername'])?> &nbsp; <b>Registration No:</b> <?=e($record['admission_no'])?> &nbsp; <b>Class:</b> <?=e($record['class_name'].$record['section'])?></p><p><b>Academic year:</b> <?=e($year?:'All available years')?></p><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Session</th><th>Term</th><th>Subject</th><th>CA</th><th>Exam</th><th>Total</th><th>Grade</th><th>Remarks</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['session_name'])?></td><td><?=e($r['term_name'])?></td><td><?=e($r['subject_name'])?></td><td><?=$r['ca_score']?></td><td><?=$r['exam_score']?></td><td><?=$r['total']?></td><td><?=e($r['grade'])?></td><td><?=e($r['remarks'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p>No results found for this selection.</p><?php endif;?></div><button class="btn btn-success mt-3" onclick="window.print()">Print / Save transcript as PDF</button><style>@media print{nav,aside,form,.btn,footer{display:none!important}main{width:100%!important}.card{border:0!important}}</style><?php endif;?><?php require __DIR__.'/../includes/footer.php';
